import { z } from 'zod';

// The CLI's machine output (`--json`, BF-042): one envelope per command, stable, published as JSON Schema in
// `schemas/cli-output/` (regenerated by `pnpm --filter @bf/sitekit schemas`, checked in CI).

export const EXIT = { ok: 0, issues: 1, usage: 2, internal: 3 } as const;

const Path = z.array(z.union([z.string(), z.number()]));

export const IssueOutput = z.object({
  path: Path,
  at: z.string(),
  code: z.string(),
  severity: z.enum(['error', 'warning']),
  message: z.string(),
  hint: z.string(),
});

export const LintIssueOutput = z.object({
  rule: z.string(),
  severity: z.enum(['error', 'warning']),
  path: Path,
  at: z.string(),
  locale: z.string(),
  message: z.string(),
  hint: z.string(),
  fix: z.string().optional(),
});

export const OUTPUT_SCHEMAS = {
  envelope: z
    .object({
      command: z.string(),
      ok: z.boolean().describe('false when issues were found or the site is not done (exit code 1).'),
      exitCode: z.union([z.literal(0), z.literal(1), z.literal(2), z.literal(3)]),
      data: z.unknown(),
      error: z.string().optional().describe('Usage or internal error (exit codes 2 and 3).'),
    })
    .meta({ title: 'sitekit --json output' }),
  validate: z
    .object({ errors: z.number().int(), issues: z.array(IssueOutput) })
    .meta({ title: 'sitekit validate' }),
  'lint-copy': z
    .object({ errors: z.number().int(), fixed: z.number().int(), issues: z.array(LintIssueOutput) })
    .meta({ title: 'sitekit lint-copy' }),
  check: z
    .object({
      done: z.boolean(),
      blocking: z.array(
        z.object({
          kind: z.string(),
          at: z.string().optional(),
          message: z.string(),
          hint: z.string().optional(),
        }),
      ),
      warnings: z.array(
        z.object({
          kind: z.string(),
          at: z.string().optional(),
          message: z.string(),
          hint: z.string().optional(),
        }),
      ),
      counts: z.object({
        validationErrors: z.number().int(),
        lintErrors: z.number().int(),
        pagesRendered: z.number().int(),
        screenshots: z.number().int(),
      }),
      screenshots: z.array(
        z.object({
          page: z.string(),
          locale: z.string(),
          viewport: z.string(),
          file: z.string(),
          width: z.number(),
          height: z.number(),
        }),
      ),
      durationMs: z.number().int(),
    })
    .meta({ title: 'sitekit check' }),
} as const;

export function outputSchemaFiles(): Map<string, string> {
  return new Map(
    Object.entries(OUTPUT_SCHEMAS).map(([name, schema]) => [
      `${name}.schema.json`,
      `${JSON.stringify(z.toJSONSchema(schema, { target: 'draft-2020-12', io: 'output' }), null, 2)}\n`,
    ]),
  );
}
